const STORAGE_KEY = 'dsh-tang-agent:last-run';

function useLang() {
  const locale = tangCtx && tangCtx.get ? tangCtx.get('locale') : undefined;
  const [, force] = React.useState(0);
  React.useEffect(() => {
    if (!locale || typeof locale.subscribe !== 'function') return undefined;
    const off = locale.subscribe(() => force((n) => n + 1));
    return () => {
      if (typeof off === 'function') off();
    };
  }, [locale]);
  let active = 'zh';
  try {
    if (locale && typeof locale.getLocale === 'function') active = (locale.getLocale() || {}).active || 'zh';
  } catch {
    active = 'zh';
  }
  return String(active).toLowerCase().slice(0, 2) === 'zh' ? 'zh' : 'en';
}

function useRun() {
  const [runId, setRunId] = React.useState(() => {
    try {
      return window.localStorage.getItem(STORAGE_KEY) || '';
    } catch {
      return '';
    }
  });
  const [run, setRun] = React.useState(null);
  const [error, setError] = React.useState('');
  const timer = React.useRef(null);

  React.useEffect(() => {
    if (!runId) return undefined;
    let stopped = false;
    let source;
    let pollTimer;

    const poll = () => {
      if (stopped) return;
      fetch(`/api/tang/runs/${encodeURIComponent(runId)}`)
        .then((response) => (response.ok ? response.json() : Promise.reject(new Error(`HTTP ${response.status}`))))
        .then((payload) => {
          setRun(payload);
          if (payload.status !== 'running') stopped = true;
        })
        .catch((reason) => setError(String(reason.message || reason)))
        .finally(() => {
          if (!stopped) pollTimer = setTimeout(poll, 1_200);
        });
    };

    try {
      source = new EventSource(`/api/tang/runs/${encodeURIComponent(runId)}/stream`);
      source.onmessage = (event) => {
        try {
          const payload = JSON.parse(event.data);
          setRun(payload);
          setError('');
          if (payload.status !== 'running' && source) source.close();
        } catch {
          /* ignore malformed frame */
        }
      };
      source.onerror = () => {
        if (source) source.close();
        poll();
      };
    } catch {
      poll();
    }

    return () => {
      stopped = true;
      if (source) source.close();
      if (pollTimer) clearTimeout(pollTimer);
      if (timer.current) clearTimeout(timer.current);
    };
  }, [runId]);

  // 工具/其他会话启动的朝议也可能有 pending 审批；面板自动附着到该 run，避免审批不可见。
  React.useEffect(() => {
    let stopped = false;
    const check = async () => {
      try {
        const list = await fetch('/api/tang/runs').then((response) => (response.ok ? response.json() : []));
        for (const item of list) {
          if (item.status !== 'running' || item.id === runId) continue;
          const detail = await fetch(`/api/tang/runs/${encodeURIComponent(item.id)}`).then((response) =>
            response.ok ? response.json() : null,
          );
          if (detail && (detail.approvals || []).some((approval) => approval.status === 'pending')) {
            if (!stopped) setRunId(item.id);
            return;
          }
        }
      } catch {
        /* 面板自动附着失败不影响当前 run */
      }
    };
    const interval = setInterval(check, 5_000);
    check();
    return () => {
      stopped = true;
      clearInterval(interval);
    };
  }, [runId]);

  const remember = (id) => {
    setRunId(id);
    try {
      window.localStorage.setItem(STORAGE_KEY, id);
    } catch {
      /* ignore */
    }
  };

  const start = async (body) => {
    setError('');
    try {
      const response = await fetch('/api/tang/run', {
        method: 'POST',
        headers: { 'content-type': 'application/json', 'x-tang-ui': '1' },
        body: JSON.stringify(body),
      });
      const payload = await response.json();
      if (!response.ok) throw new Error(payload.error || `HTTP ${response.status}`);
      remember(payload.runId);
      setRun(null);
    } catch (reason) {
      setError(String(reason.message || reason));
    }
  };

  const cancel = async () => {
    if (!runId) return;
    try {
      await fetch(`/api/tang/runs/${encodeURIComponent(runId)}/cancel`, {
        method: 'POST',
        headers: { 'x-tang-ui': '1' },
      });
    } catch (reason) {
      setError(String(reason.message || reason));
    }
  };

  const decideApproval = async (id, decision) => {
    try {
      await fetch(`/api/tang/approvals/${encodeURIComponent(id)}`, {
        method: 'POST',
        headers: { 'content-type': 'application/json', 'x-tang-ui': '1' },
        body: JSON.stringify({ decision }),
      });
    } catch (reason) {
      setError(String(reason.message || reason));
    }
  };

  const clear = () => {
    setRunId('');
    setRun(null);
    setError('');
    try {
      window.localStorage.removeItem(STORAGE_KEY);
    } catch {
      /* ignore */
    }
  };

  return { runId, run, error, start, cancel, clear, decideApproval, resume: () => setRunId((id) => id) };
}

const STAGE_INDEX = {
  idle: -1,
  drafting: 1,
  revising: 1,
  feasibility: 2,
  reviewing: 3,
  dispatching: 4,
  executing: 5,
  aggregating: 5,
  completed: 6,
  escalated: 3,
  single: 5,
  quick: 1,
  cancelled: -1,
  failed: -1,
};

const ROLE_ORDER = ['zhongshu', 'qintianjian', 'menxia', 'shangshu', 'works', 'justice', 'war', 'rites', 'revenue', 'personnel'];

function Rail({ phase, t }) {
  const labels = [t.stage === 'Stage' ? 'Emperor' : '皇帝', '中书省', '钦天监', '门下省', '尚书省', '六部'];
  const index = STAGE_INDEX[phase] ?? -1;
  return h(
    'div',
    { className: 'tda-rail', role: 'list', 'aria-label': 'court stages' },
    labels.map((label, step) => {
      let status = 'pending';
      if (phase === 'escalated' && step === 3) status = 'error';
      else if (phase === 'failed' && step === 5) status = 'error';
      else if (index > step) status = 'done';
      else if (index === step) status = 'active';
      return h(
        'div',
        { key: label, className: 'tda-rail-node is-' + status, role: 'listitem' },
        h('span', { className: 'tda-rail-dot' }, String(step + 1)),
        h('span', { className: 'tda-rail-label' }, label),
      );
    }),
  );
}

function Head({ title, en, right }) {
  return h(
    'div',
    { className: 'tda-card-head' },
    h('span', { className: 'tda-eyebrow' }, title, h('small', null, en || '')),
    right || null,
  );
}

function AgentGrid({ run, t }) {
  const agents = run?.agents || {};
  const [selected, setSelected] = React.useState('shangshu');
  const getAgent = (role) =>
    agents[role] || {
      role,
      name: CourtMeta.ROLE_LABELS[role] || role,
      status: 'idle',
      model: '—',
      sessionId: '',
      stream: '',
      text: '',
      toolCalls: [],
    };
  const statusLabel = (status) =>
    status === 'running' ? t.running : status === 'done' ? t.done : status === 'blocked' ? t.blocked : status === 'failed' ? t.failed : t.idle;
  const node = (role, kind) => {
    const agent = getAgent(role);
    const status = agent.status || 'idle';
    return h(
      'button',
      {
        type: 'button',
        key: role,
        className: `tda-org-node tda-org-${kind} is-${status}` + (selected === role ? ' is-selected' : ''),
        onClick: () => setSelected(role),
        title: agent.name,
      },
      h('span', { className: 'tda-org-dot is-' + status, 'aria-hidden': 'true' }),
      h('span', { className: 'tda-org-name' }, agent.name),
      h('span', { className: 'tda-org-status' }, statusLabel(status)),
    );
  };
  const emperorStatus = !run
    ? 'idle'
    : run.status === 'running'
      ? 'running'
      : run.status === 'completed'
        ? 'done'
        : run.status === 'failed'
          ? 'failed'
          : 'idle';
  const selectedAgent = getAgent(selected);

  return h(
    'section',
    { className: 'tda-card' },
    h(Head, {
      title: t.agents,
      en: `${run?.agentCount || 0} LLM / ${ROLE_ORDER.length}`,
      right: h('span', { className: 'tda-badge tda-badge-real' }, t.realBadge),
    }),
    h(
      'div',
      { className: 'tda-org' },
      h(
        'div',
        { className: 'tda-org-emperor is-' + emperorStatus },
        h('span', { className: 'tda-org-dot is-' + emperorStatus }),
        h('span', { className: 'tda-org-name' }, t.emperor),
        h('span', { className: 'tda-org-status' }, statusLabel(emperorStatus)),
      ),
      h('div', { className: 'tda-org-trunk' }),
      h('div', { className: 'tda-org-departments' }, [
        node('menxia', 'dept'),
        node('shangshu', 'dept'),
        node('zhongshu', 'dept'),
      ]),
      h('div', { className: 'tda-org-bus' }),
      h(
        'div',
        { className: 'tda-org-ministries' },
        CourtMeta.MINISTRY_ORDER.map((role) => node(role, 'ministry')),
      ),
      h(
        'div',
        { className: 'tda-org-aux' },
        h('span', { className: 'tda-org-aux-line', 'aria-hidden': 'true' }),
        node('qintianjian', 'aux'),
      ),
    ),
    h(
      'div',
      { className: 'tda-org-detail' },
      h(
        'div',
        { className: 'tda-org-detail-head' },
        h('strong', null, selectedAgent.name),
        h('span', { className: 'tda-badge' }, statusLabel(selectedAgent.status || 'idle')),
        h('span', { className: 'tda-agent-meta' }, `${t.model}: ${selectedAgent.model || '—'}`),
        selectedAgent.sessionId
          ? h('span', { className: 'tda-agent-meta' }, `${t.session}: ${selectedAgent.sessionId.slice(0, 8)}`)
          : null,
      ),
      h(
        'div',
        { className: 'tda-agent-stream' },
        (selectedAgent.stream || selectedAgent.text || '').slice(-1200) ||
          (selectedAgent.status === 'idle' ? t.awaiting : t.stream + '…'),
      ),
      selectedAgent.error ? h('div', { className: 'tda-agent-error' }, selectedAgent.error) : null,
      h(
        'div',
        { className: 'tda-tools' },
        (selectedAgent.toolCalls || []).length === 0
          ? h('span', { className: 'tda-pending' }, t.noTools)
          : (selectedAgent.toolCalls || []).map((call, index) =>
              h(
                'div',
                { className: 'tda-tool', key: call.name + index },
                h('div', { className: 'tda-tool-name' }, '⚙ ' + call.name),
                h('div', { className: 'tda-tool-args' }, JSON.stringify(call.args)),
                h(
                  'div',
                  { className: 'tda-tool-result' + (call.error ? ' is-error' : '') },
                  call.error || call.result || '…',
                ),
              ),
            ),
      ),
    ),
  );
}

